import{_ as n,a0 as p,w as h,s as o,ao as d,I as l,x as i,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"10 個 Linux 中方便的 Bash 別名 | LCTT x X-CMD","titleTemplate":false,"description":"10 個 Linux 中方便的 Bash 別名 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10 個 Linux 中方便的 Bash 別名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10 個 Linux 中方便的 Bash 別名 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180928 10 handy Bash aliases for Linux","title":"10 個 Linux 中方便的 Bash 別名","tag":"201810","desc":""},"relativePath":"201810/20180928 10 handy Bash aliases for Linux.md","filePath":"[post].md"}'),r={name:"201810/20180928 10 handy Bash aliases for Linux.md"};function g(u,s,k,b,c,f){const a=p("Link");return h(),o("div",null,[s[15]||(s[15]=d('<h1 id="_10-個-linux-中方便的-bash-別名" tabindex="-1">10 個 Linux 中方便的 Bash 別名 <a class="header-anchor" href="#_10-個-linux-中方便的-bash-別名" aria-label="Permalink to “10 個 Linux 中方便的 Bash 別名”">​</a></h1><blockquote><p>對 Bash 長命令使用壓縮的版本來更有效率。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/bash_command_line.png?itok=k4z94W2U" alt=""></p><p>你有多少次在命令列上輸入一個長命令，並希望有一種方法可以保存它以供日後使用？這就是 Bash 別名派上用場的地方。它們允許你將長而神秘的命令壓縮為易於記憶和使用的東西。需要一些例子來幫助你入門嗎？沒問題！</p><p>要使用你創建的 Bash 別名，你需要將其添加到 <code>.bash_profile</code> 中，該文件位於你的家目錄中。請注意，此文件是隱藏的，並只能從命令列訪問。編輯此文件的最簡單方法是使用 Vi 或 Nano 之類的東西。</p><h3 id="_10-個方便的-bash-別名" tabindex="-1">10 個方便的 Bash 別名 <a class="header-anchor" href="#_10-個方便的-bash-別名" aria-label="Permalink to “10 個方便的 Bash 別名”">​</a></h3><p>1、 你有幾次遇到需要解壓 .tar 文件但無法記住所需的確切參數？別名可以幫助你！只需將以下內容添加到 <code>.bash_profile</code> 中，然後使用 <code>untar FileName</code> 解壓縮任何 .tar 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias untar=&#39;tar -zxvf &#39;</span></span></code></pre></div><p>2、 想要下載的東西，但如果出現問題可以恢復嗎？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias wget=&#39;wget -c &#39;</span></span></code></pre></div><p>3、 是否需要為新的網絡帳户生成隨機的 20 個字符的密碼？沒問題。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias getpass=&quot;openssl rand -base64 20&quot;</span></span></code></pre></div><p>4、 下載文件並需要測試校驗和？我們也可做到。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias sha=&#39;shasum -a 256 &#39;</span></span></code></pre></div><p>5、 普通的 <code>ping</code> 將永遠持續下去。我們不希望這樣。相反，讓我們將其限制在五個 <code>ping</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ping=&#39;ping -c 5&#39;</span></span></code></pre></div><p>6、 在任何你想要的文件夾中啓動 Web 服務器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias www=&#39;python -m SimpleHTTPServer 8000&#39;</span></span></code></pre></div><p>7、 想知道你的網絡有多快？只需下載 Speedtest-cli 並使用此別名即可。你可以使用 <code>speedtest-cli --list</code> 命令選擇離你所在位置更近的服務器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias speed=&#39;speedtest-cli --server 2406 --simple&#39;</span></span></code></pre></div><p>8、 你有多少次需要知道你的外部 IP 地址，但是不知道如何獲取？我也是。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ipe=&#39;curl ipinfo.io/ip&#39;</span></span></code></pre></div><p>9、 需要知道你的本地 IP 地址？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ipi=&#39;ipconfig getifaddr en0&#39;</span></span></code></pre></div><p>10、 最後，讓我們清空屏幕。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias c=&#39;clear&#39;</span></span></code></pre></div><p>如你所見，Bash 別名是一種在命令列上簡化生活的超級簡便方法。想了解更多信息？我建議你 Google 搜索“Bash 別名”或在 Github 中看下。</p><hr>',28)),l("p",null,[s[1]||(s[1]=i("via: ",-1)),e(a,{href:"https://opensource.com/article/18/9/handy-bash-aliases"},{default:t(()=>[...s[0]||(s[0]=[i("https://opensource.com/article/18/9/handy-bash-aliases",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=i("作者：",-1)),e(a,{href:"https://opensource.com/users/pmullins"},{default:t(()=>[...s[2]||(s[2]=[i("Patrick H.Mullins",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const C=n(r,[["render",g]]);export{x as __pageData,C as default};
